#include "PluginEditor.h"
MinimalChainAudioProcessorEditor::MinimalChainAudioProcessorEditor(MinimalChainAudioProcessor&x):AudioProcessorEditor(&x),p(x){
add("delayTime","TIME");add("delayFeedback","FEEDBACK");add("delayMix","MIX");add("lpCutoff","LP CUT");add("lpRes","LP RES");add("hpCutoff","HP CUT");add("hpRes","HP RES");add("distTone","TONE");add("distAmount","AMOUNT");add("distMix","MIX");add("compInput","INPUT");add("compPeak","PEAK REDUCTION");add("output","OUTPUT");setSize(900,430);}
void MinimalChainAudioProcessorEditor::add(const juce::String&i,const juce::String&n){auto k=std::make_unique<K>();k->s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k->s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,88,20);k->s.setDoubleClickReturnValue(true,true);k->l.setText(n,juce::dontSendNotification);k->l.setJustificationType(juce::Justification::centred);k->a=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,i,k->s);addAndMakeVisible(k->s);addAndMakeVisible(k->l);ks.push_back(std::move(k));}
void MinimalChainAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff111111));g.setColour(juce::Colours::white);g.setFont(24);g.drawText("MINIMAL CHAIN",24,18,400,30,juce::Justification::left);}
void MinimalChainAudioProcessorEditor::resized(){int w=62,gap=7,y=70;for(size_t i=0;i<ks.size();++i){int x=20+(int)i*(w+gap);ks[i]->s.setBounds(x,y,w,90);ks[i]->l.setBounds(x-5,y+90,w+10,34);}}
